ns.Data.locales.zhCN = ns.Data._freeze({
  camp = {
    camp_spell_1229432 = { desc = "制作一顶营地帐篷。", effect = "搭建一座帐篷，使你和附近坐下的其他人获得充分休息经验值，最多可累积至当前等级所需经验值的5%。若已有的充分休息经验超过该数值，则不生效。 需要附近有营火。所有露营功能共享1小时冷却时间。", name = "营地帐篷" },
    camp_spell_1229504 = { desc = "制作一面阵营旗帜。", effect = "展开一面旗帜，使你和附近坐着的其他部落成员的精神提高32。与神圣之灵互斥。 需要附近有营火。所有露营功能共享1小时冷却时间。", name = "阵营旗帜" },
    camp_spell_1229517 = { desc = "制作一把营地椅子。", effect = "组装一把营地椅子，使你和附近坐下的其他人所有法术和攻击的爆击几率提高2%，与枭兽光环不叠加。 需要附近有营火。所有露营功能共享1小时冷却时间。", name = "营地椅子" },
    camp_spell_1229705 = { desc = "制作一支熏香蜡烛。", effect = "点燃一根熏香蜡烛，使你和附近坐下的其他人智力提高25点，与奥术智慧不叠加。 需要附近有营火。所有露营功能共享1小时冷却时间。", name = "熏香蜡烛" },
    camp_spell_1229737 = { desc = "制作一个基础营火。", effect = "生起一堆基础营火，可以用来烹饪，并允许额外放置最多3个露营设施。在附近坐下或制造物品持续1分钟的玩家将获得其他露营设施的增益。", name = "基础营火" },
    camp_spell_1229745 = { desc = "制作一个鱼缸。", effect = "放置一个小的鱼缸，使你和附近坐下的其他人所有属性提高8%，与王者祝福不叠加。 需要附近有营火。所有露营功能共享1小时冷却时间。", name = "鱼缸" },
    camp_spell_1230117 = { desc = "制作一个急救包。", effect = "打开一个急救包，使你和附近坐下的其他人耐力提高56点，与真言术：韧不叠加。 需要附近有营火。所有露营功能共享1小时冷却时间。", name = "急救包" },
    camp_spell_1230161 = { desc = "制作一块磁石。", effect = "竖起一块磁石，使你和附近坐下的其他人近战攻击强度提高90，与力量祝福互斥。 需要附近有营火。所有露营功能共享1小时冷却时间。", name = "磁石" },
    camp_spell_1230171 = { desc = "制作一个磨刀石。", effect = "搭建一个磨刀石，使你和附近坐下的其他人力量提高34，与大地之力图腾互斥。 需要附近有营火。所有露营功能共享1小时冷却时间。", name = "磨刀石" },
    camp_spell_1230564 = { desc = "制作一口法力之井。", effect = "建造一口法力之井，使你和附近坐下的其他人每5秒恢复29点法力值，与智慧祝福不叠加。 需要附近有营火。所有露营功能共享1小时冷却时间。", name = "法力之井" },
    camp_spell_1230643 = { desc = "制作一把附魔的鲁特琴。", effect = "召唤一把附魔的鲁特琴，使你和附近坐下的其他人获得308 点护甲值，13点所有属性加成，以及22点所有抗性加成，与野性印记不叠加。 需要附近有营火。所有露营功能共享1小时冷却时间。", name = "附魔的鲁特琴" },
    camp_spell_1230656 = { desc = "制作一个试剂机器人。", effect = "召唤一个试剂机器人，允许你和附近的其他人购买材料。 需要附近有营火。所有露营功能共享1小时冷却时间。", name = "试剂机器人" },
    camp_spell_1262975 = { desc = "制作一个岩石园。", effect = "放置一个岩石园，随着时间的推移会生成普通的采矿点，并提供磁石的所有增益。需要附近有营火。 可以放置在磁石上以将其替换。所有露营功能共享1小时冷却时间。", name = "岩石园" },
    camp_spell_1262978 = { desc = "制作曲奇的大餐。", effect = "摆出曲奇的大餐，其中包含可提高耐力的食物。 需要附近有烹饪用火。所有露营功能共享1小时冷却时间。", name = "曲奇的大餐" },
    camp_spell_1262980 = { desc = "制作一座温室。", effect = "放置一个温室，随着时间的推移，播种的种子会生长成草药，并提供熏香蜡烛的所有增益。需要附近有营火。 可以放置在熏香蜡烛上以将其替换。 所有露营功能共享1小时冷却时间。", name = "温室" },
    camp_spell_1262982 = { desc = "制作一张捕兽者工作台。", effect = "放置一个捕兽者工作台，内含1个陷阱，并提供营地椅子的所有增益。需要附近有营火。 可以放置在营地椅子上以将其替换。 所有露营功能共享1小时冷却时间。", name = "捕兽者工作台" },
    camp_spell_1262985 = { desc = "制作一本野外指南。", effect = "放置一本野外指南，允许玩家阅读并获得追踪野兽技能，并提供营地椅子的所有增益。需要附近有营火。 可以放置在营地椅子上以将其替换。 所有露营功能共享1小时冷却时间。", name = "野外指南" },
    camp_spell_1262990 = { desc = "制作一个钓鱼架。", effect = "放置一个钓鱼架，使你能够钓到优秀的鱼，持续1小时，提供钓鱼技能鱼饵，并提供鱼缸的所有增益。需要附近有营火。 可以放置在鱼缸上以将其替换。所有露营功能共享1小时冷却时间。", name = "钓鱼架" },
    camp_spell_1262996 = { desc = "制作一项毒素研究。", effect = "放置一个毒素研究，内含治疗药水和抗毒药剂，并提供急救包的所有增益。需要附近有营火。 可以放置在急救包上以将其替换。 所有露营功能共享1小时冷却时间。", name = "毒素研究" },
    camp_spell_1262998 = { desc = "制作一间钓鱼小屋。", effect = "放置一个钓鱼小屋，使你能够钓到稀有的鱼，持续1小时，提供钓鱼技能鱼饵，并提供鱼缸的所有增益。需要附近有营火。 可以放置在鱼缸上以将其替换。所有露营功能共享1小时冷却时间。", name = "钓鱼小屋" },
    camp_spell_1263001 = { desc = "制作一座瘟疫医生实验室。", effect = "放置一个瘟疫医生实验室，内含治疗药水和药膏，并提供急救包的所有增益。需要附近有营火。 可以放置在急救包上以将其替换。所有露营功能共享1小时冷却时间。", name = "瘟疫医生实验室" },
    camp_spell_1263005 = { desc = "制作一个发酵桶。", effect = "放置一个发酵桶，允许制造特定材料，并提供法力之井的所有增益。需要附近有营火。 可以放置在法力之井上以将其替换。所有露营功能共享1小时冷却时间。", name = "发酵桶" },
