    camp_spell_1263034 = { desc = "制作一个修理机器人。", effect = "召唤一个修理机器人，允许你和附近的其他人购买材料和修理装备。需要附近有营火。 可以放置在试剂机器人上以将其替换。所有露营功能共享1小时冷却时间。", name = "修理机器人" },
